import {componentArtwork,artworkStyle} from './component-artwork.mjs';
import {conventionalSignalStudy} from './educational-truth.mjs';
import {homepageCircuit,homepageStateKey,homepageSpecificationKey} from './homepage-state.mjs';
const esc=value=>String(value).replace(/[&"<>]/g,c=>({'&':'&amp;','"':'&quot;','<':'&lt;','>':'&gt;'}[c]));
// Only geometry/spacing and annotation are projected here. Electrical selection,
// terminal identities and tone loading come from the shared conductive graph.
export function homepageEditorial({compact=false,circuit=homepageCircuit()}={}){
 const s=conventionalSignalStudy(circuit),positions=compact?[[20,20,.7],[230,120,.7],[110,290,.7],[285,500,1],[275,650,.6],[100,650,.75]]:[[60,65,.8],[330,95,.8],[640,52,.8],[970,96,1],[830,265,.65],[710,340,1]],parts=[['pickup',s.pickup],['selector',s.selector],['volume',s.volume],['output',s.jack],['tone',s.tone],['capacitor',s.cap]].map(([id,p],i)=>({id,p,x:positions[i][0],y:positions[i][1],scale:positions[i][2]}));
 if(s.cap.value!=='0.047µF')throw Error('Unexpected homepage tone capacitor authority');
 const anchor=(id,ref)=>{const a=parts.find(p=>p.id===id),t=a.p.terminals[ref];return [a.x+t.x*a.scale,a.y+t.y*a.scale];},pair=a=>a.join(' ');
 const selectedLead=circuit.connections.find(w=>w.from===s.pickup.id+'.hot'&&w.to.startsWith(s.selector.id+'.')),closed=circuit.contacts.find(pair=>pair.includes(selectedLead.to)),selectedThrow=closed?.find(ref=>ref!==selectedLead.to);if(!selectedThrow||!circuit.connections.some(w=>w.from===selectedThrow&&w.to===s.volume.id+'.lug3'))throw Error('Selected blade contact unavailable');
 const hot=anchor('pickup','hot'),selIn=anchor('selector',selectedLead.to.split('.')[1]),selOut=anchor('selector',selectedThrow.split('.')[1]),input=anchor('volume','lug3'),wiper=anchor('volume','lug2'),tip=anchor('output','tip'),sleeve=anchor('output','sleeve'),capIn=anchor('capacitor','a'),capOut=anchor('capacitor','b'),toneIn=anchor('tone','lug2'),toneGround=anchor('tone','lug1');
 const primary=compact?[`M${pair(hot)}H190V${selIn[1]}H${selIn[0]}`,`M${pair(selOut)}H380V360H${input[0]}V${input[1]}`,`M${pair(wiper)}V460H360V${tip[1]}H${tip[0]}`]:[`M${pair(hot)}H260V${selIn[1]}H${selIn[0]}`,`M${pair(selOut)}H545V${input[1]}H${input[0]}`,`M${pair(wiper)}V215H1060V${tip[1]}H${tip[0]}`];
 const loading=`M${pair(input)}V${capIn[1]}H${capIn[0]}M${pair(capOut)}V${compact?790:385}H${toneIn[0]}V${toneIn[1]}M${pair(toneGround)}V${compact?815:405}m-14 0h28m-23 7h18m-13 7h8`,id=compact?'home-path-compact':'home-path';
 const glyphs=parts.map(a=>`<g data-signal-stage="${a.id}" data-shared-artwork="${a.p.type}" data-component="${a.p.id}" transform="translate(${a.x} ${a.y}) scale(${a.scale})">${componentArtwork({...a.p,value:a.id==='tone'?'TONE':a.p.value,showState:false,displaySelectorPosition:false},{mode:'editorial',detail:'compact'})}</g>`).join('');
 const labels=compact?[[90,135,'PICKUP'],[280,230,'SELECTOR'],[110,420,'VOLUME'],[280,605,'OUTPUT · TIP'],[100,700,'0.047 µF'],[275,845,'TONE / TO GROUND']]:[[135,250,'PICKUP'],[405,250,'SELECTOR'],[640,250,'VOLUME'],[970,250,'OUTPUT · TIP'],[710,377,'0.047 µF'],[830,454,'TONE / TO GROUND']];
 return `<svg xmlns="http://www.w3.org/2000/svg" class="home-editorial-path${compact?' home-editorial-compact':''}" data-home-renderer="editorial-v1" data-artwork-system="v2" data-diagram-surface="cream" data-circuit-state="${homepageStateKey(circuit)}" data-homepage-specification="${esc(homepageSpecificationKey(circuit))}" viewBox="0 0 ${compact?'420 880':'1100 480'}" role="img" aria-labelledby="${id}-title ${id}-description"><title id="${id}-title">Pickup to output: the passive signal path</title><desc id="${id}-description">Pickup and selector feed volume input lug 3. Volume wiper lug 2 leads to output jack TIP. The 0.047 µF tone capacitor branches from input lug 3 through the tone control to ground. Conceptual map, not a soldering diagram.</desc><style>${artworkStyle}
.home-editorial-path{--art-paper:#eee8db;--art-metal:#a3a69e}.home-editorial-path .board,.home-editorial-path .blade-wafer{fill:#d0b98c;stroke:#796c51}.home-editorial-path text{fill:#3c3d32;font:13px monospace}.home-editorial-path .micro,.home-editorial-path .coil-label,.home-editorial-path .terminal-label,.home-editorial-path .blade-terminal-label,.home-editorial-path .blade-bank-label,.home-editorial-path .blade-caption,.home-editorial-path .blade-orientation{display:none}.home-editorial-path .signal-rest,.home-editorial-path .signal-travel{fill:none;stroke-linejoin:round;stroke-linecap:round;stroke-width:3}.home-editorial-path .signal-rest{stroke:#827555}.home-editorial-path .signal-travel{stroke:#ad8740;stroke-dasharray:18 320;stroke-width:3.5;animation:home-signal-travel 7s linear infinite}.home-editorial-path .signal-travel[data-travel-stage="1"]{animation-delay:-2s}.home-editorial-path .signal-travel[data-travel-stage="2"]{animation-delay:-4s}.home-editorial-path .tone-concept{fill:none;stroke:#8b7c60;stroke-width:2;stroke-dasharray:5 4}.home-editorial-path .ground-concept{fill:none;stroke:#72786b;stroke-width:2}.home-editorial-path .signal-destination{fill:#bd9a56;stroke:#79643d;stroke-width:2}@keyframes home-signal-travel{to{stroke-dashoffset:-338}}@media(prefers-reduced-motion:reduce){.home-editorial-path .signal-travel{animation:none;display:none}}
</style>${glyphs}<g data-main-signal="${s.pickup.id}.hot selector ${s.volume.id}.lug3 ${s.volume.id}.lug2 jack.tip">${primary.map((path,i)=>`<path class="signal-rest" data-home-trace="${i}"${i===1?` data-signal-input="${s.volume.id}.lug3"`:i===2?` data-signal-output="${s.volume.id}.lug2" data-home-signal-to="jack.tip"`:''} d="${path}"/>`).join('')}${primary.map((path,i)=>`<path data-travel-stage="${i}" class="signal-travel" aria-hidden="true" d="${path}"/>`).join('')}</g><path class="tone-concept" data-tone-branch="loading" data-from="${s.volume.id}.lug3" data-to="jack.sleeve" data-via="${s.cap.id}.a ${s.cap.id}.b ${s.tone.id}.lug2 ${s.tone.id}.lug1" d="${loading}"/><path class="ground-concept" data-ground-from="jack.sleeve" d="M${pair(sleeve)}V${sleeve[1]+39}m-12 0h24m-19 7h14m-9 7h4"/><circle class="signal-destination" data-terminal="jack.tip" cx="${tip[0]}" cy="${tip[1]}" r="5"/><circle data-terminal="jack.sleeve" cx="${sleeve[0]}" cy="${sleeve[1]}" r="4" fill="none" stroke="#72786b"/>${labels.map(([x,y,text])=>`<text x="${x}" y="${y}" text-anchor="middle">${text}</text>`).join('')}</svg>`;
}
